import { realpathSync, statSync } from "node:fs";
import os from "node:os";
import path from "node:path";

export type Platform = "win32" | "posix";

export interface PathPolicy {
  platform: Platform;
  /** Roots a work folder must sit inside. Should already be real paths. */
  allowedRoots: string[];
  /** The Town Hall data folder (database, runtime.json with the token, worktrees). */
  dataDir: string;
  homeDir: string;
  /** Folders refused along with everything inside them. */
  systemDirs: string[];
}

export type PathCheck = { ok: true; path: string } | { ok: false; reason: string };

function lib(platform: Platform): path.PlatformPath {
  return platform === "win32" ? path.win32 : path.posix;
}

/** Normalised comparison key: resolved, no trailing separator, lower-cased on Windows. */
export function pathKey(p: string, platform: Platform): string {
  const l = lib(platform);
  let n = l.normalize(p);
  if (n.length > 1 && (n.endsWith("\\") || n.endsWith("/")) && !isDriveRoot(n, platform)) n = n.slice(0, -1);
  if (platform === "win32") n = n.replace(/\//g, "\\").toLowerCase();
  return n;
}

export function samePath(a: string, b: string, platform: Platform): boolean {
  return pathKey(a, platform) === pathKey(b, platform);
}

/** True when `child` equals `parent` or lies inside it. */
export function isInside(child: string, parent: string, platform: Platform): boolean {
  const c = pathKey(child, platform);
  const p = pathKey(parent, platform);
  if (c === p) return true;
  const sep = platform === "win32" ? "\\" : "/";
  const prefix = p.endsWith(sep) ? p : p + sep;
  return c.startsWith(prefix);
}

export function isDriveRoot(p: string, platform: Platform): boolean {
  if (platform === "win32") return /^[a-zA-Z]:[\\/]?$/.test(p.trim());
  return lib(platform).normalize(p) === "/";
}

export function isUncOrDevicePath(p: string): boolean {
  return p.startsWith("\\\\") || p.startsWith("//") || /^\\\?\\/.test(p);
}

export function defaultSystemDirs(platform: Platform, env: Record<string, string | undefined> = process.env): string[] {
  if (platform === "win32") {
    const drive = (env.SystemDrive ?? "C:").replace(/[\\/]$/, "");
    const dirs = [
      env.SystemRoot ?? `${drive}\\Windows`,
      env.ProgramFiles ?? `${drive}\\Program Files`,
      env["ProgramFiles(x86)"] ?? `${drive}\\Program Files (x86)`,
      env.ProgramData ?? `${drive}\\ProgramData`,
      `${drive}\\Windows`,
      `${drive}\\Program Files`,
      `${drive}\\Program Files (x86)`,
      `${drive}\\ProgramData`,
      `${drive}\\$Recycle.Bin`,
      `${drive}\\System Volume Information`,
      `${drive}\\Recovery`,
      `${drive}\\Boot`,
    ];
    return [...new Set(dirs)];
  }
  return [
    "/bin",
    "/boot",
    "/dev",
    "/etc",
    "/lib",
    "/lib64",
    "/proc",
    "/root",
    "/sbin",
    "/sys",
    "/usr",
    "/var",
    "/System",
    "/Library",
    "/Applications",
    "/private/etc",
  ];
}

/**
 * Policy checks on a path that has already been resolved to its real location.
 * Pure, so the Windows rules can be tested on any platform.
 */
export function checkResolvedPath(real: string, policy: PathPolicy): PathCheck {
  const { platform } = policy;
  if (isUncOrDevicePath(real)) return { ok: false, reason: "network (UNC) and device paths are not allowed" };
  if (isDriveRoot(real, platform)) return { ok: false, reason: "a drive root cannot be a work folder" };
  if (samePath(real, policy.homeDir, platform)) return { ok: false, reason: "the home folder itself cannot be a work folder" };
  for (const dir of policy.systemDirs) {
    if (isInside(real, dir, platform)) return { ok: false, reason: "system folders cannot be work folders" };
  }
  if (isInside(real, policy.dataDir, platform) || isInside(policy.dataDir, real, platform)) {
    return { ok: false, reason: "the Town Hall data folder cannot be inside or contain a work folder" };
  }
  if (!policy.allowedRoots.some((root) => isInside(real, root, platform))) {
    return { ok: false, reason: "the folder is outside the allowed work roots" };
  }
  return { ok: true, path: real };
}

/** Lexical checks before touching the filesystem. */
export function checkInputPath(input: string, platform: Platform): PathCheck {
  const trimmed = input.trim();
  if (trimmed === "") return { ok: false, reason: "empty path" };
  if (trimmed.includes("\0")) return { ok: false, reason: "invalid characters in path" };
  if (isUncOrDevicePath(trimmed)) return { ok: false, reason: "network (UNC) and device paths are not allowed" };
  if (platform === "win32") {
    if (!/^[a-zA-Z]:[\\/]/.test(trimmed) && !/^[a-zA-Z]:$/.test(trimmed)) {
      return { ok: false, reason: "an absolute path with a drive letter is required" };
    }
  } else if (!trimmed.startsWith("/")) {
    return { ok: false, reason: "an absolute path is required" };
  }
  return { ok: true, path: lib(platform).resolve(trimmed) };
}

/** Upper-cases the drive letter so paths display consistently. */
export function canonicalDrive(p: string, platform: Platform): string {
  if (platform === "win32" && /^[a-z]:/.test(p)) return p[0]!.toUpperCase() + p.slice(1);
  return p;
}

export function currentPlatform(): Platform {
  return process.platform === "win32" ? "win32" : "posix";
}

export function realpathOrNull(p: string): string | null {
  try {
    return realpathSync.native(p);
  } catch {
    return null;
  }
}

/** Full validation of a user-supplied work folder: lexical, realpath, then policy. */
export function validateWorkFolder(input: string, policy: PathPolicy): PathCheck {
  const lexical = checkInputPath(input, policy.platform);
  if (!lexical.ok) return lexical;
  const real = realpathOrNull(lexical.path);
  if (!real) return { ok: false, reason: "the folder does not exist" };
  try {
    if (!statSync(real).isDirectory()) return { ok: false, reason: "not a folder" };
  } catch {
    return { ok: false, reason: "the folder cannot be read" };
  }
  const result = checkResolvedPath(canonicalDrive(real, policy.platform), policy);
  return result;
}

export function buildPathPolicy(opts: { workRoots: string[]; dataDir: string }): PathPolicy {
  const platform = currentPlatform();
  const real = (p: string) => canonicalDrive(realpathOrNull(p) ?? path.resolve(p), platform);
  return {
    platform,
    allowedRoots: opts.workRoots.map(real),
    dataDir: real(opts.dataDir),
    homeDir: real(os.homedir()),
    systemDirs: defaultSystemDirs(platform),
  };
}

/** Forward-slash form used in protocol objects ("D:/work/app"). */
export function displayPath(p: string): string {
  return p.replace(/\\/g, "/");
}

import { randomBytes, timingSafeEqual } from "node:crypto";

/** A fresh 32-byte launch token, base64url so it can travel in a URL fragment. */
export function generateToken(): string {
  return randomBytes(32).toString("base64url");
}

export function tokensEqual(expected: string, given: unknown): boolean {
  if (typeof given !== "string") return false;
  const a = Buffer.from(expected, "utf8");
  const b = Buffer.from(given, "utf8");
  if (a.length !== b.length) {
    // Compare anyway so the timing does not reveal the length check.
    timingSafeEqual(a, a);
    return false;
  }
  return timingSafeEqual(a, b);
}

const REDACTED = "[REDACTED]";

const PATTERNS: RegExp[] = [
  /-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]*?-----END [A-Z ]*PRIVATE KEY-----/g,
  /\bsk-ant-[A-Za-z0-9_-]{10,}/g,
  /\bsk-(?:proj-|svcacct-)?[A-Za-z0-9_-]{20,}/g,
  /\bgh[pousr]_[A-Za-z0-9]{20,}/g,
  /\bgithub_pat_[A-Za-z0-9_]{20,}/g,
  /\bxox[abposr]-[A-Za-z0-9-]{10,}/g,
  /\bAKIA[0-9A-Z]{16}\b/g,
  /\bAIza[0-9A-Za-z_-]{30,}/g,
  /\beyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}/g,
];

// key=value / key: value pairs whose key names a secret.
const KEYED = /((?:api[_-]?key|secret|token|password|passwd|pwd|auth(?:orization)?|client[_-]?secret|access[_-]?key)["']?\s*[:=]\s*["']?)([^\s"',;]{4,})/gi;
const BEARER = /\b(Bearer|Basic)\s+[A-Za-z0-9._~+/=-]{8,}/g;

const SECRET_ENV_NAMES = [
  "ANTHROPIC_API_KEY",
  "OPENAI_API_KEY",
  "CODEX_API_KEY",
  "CLAUDE_CODE_OAUTH_TOKEN",
  "GITHUB_TOKEN",
  "GH_TOKEN",
];

export class Redactor {
  private readonly literals: string[];

  constructor(extraSecrets: string[] = [], env: Record<string, string | undefined> = process.env) {
    const fromEnv = SECRET_ENV_NAMES.map((n) => env[n]).filter((v): v is string => !!v && v.length >= 8);
    this.literals = [...new Set([...extraSecrets.filter((s) => s.length >= 8), ...fromEnv])];
  }

  addSecret(secret: string): void {
    if (secret.length >= 8 && !this.literals.includes(secret)) this.literals.push(secret);
  }

  redact(text: string): string {
    let out = text;
    for (const lit of this.literals) out = out.split(lit).join(REDACTED);
    for (const p of PATTERNS) out = out.replace(p, REDACTED);
    out = out.replace(BEARER, (_m, scheme: string) => `${scheme} ${REDACTED}`);
    out = out.replace(KEYED, (_m, prefix: string) => `${prefix}${REDACTED}`);
    return out;
  }
}

/** What Buffer#toString produces for a UTF-8 sequence cut in half. */
const REPLACEMENT_CHAR = String.fromCharCode(0xfffd);

/** Truncates to at most `maxBytes` UTF-8 bytes, keeping the start. */
export function capBytes(text: string, maxBytes: number, marker = "...[truncated]"): string {
  if (Buffer.byteLength(text, "utf8") <= maxBytes) return text;
  const budget = Math.max(0, maxBytes - Buffer.byteLength(marker, "utf8"));
  let cut = Buffer.from(text, "utf8").subarray(0, budget).toString("utf8");
  // Drop a trailing partial character produced by the byte cut.
  if (cut.endsWith(REPLACEMENT_CHAR)) cut = cut.slice(0, -1);
  return cut + marker;
}

/** Keeps the last `maxBytes` UTF-8 bytes (for command output tails). */
export function tailBytes(text: string, maxBytes: number): string {
  const buf = Buffer.from(text, "utf8");
  if (buf.length <= maxBytes) return text;
  let tail = buf.subarray(buf.length - maxBytes).toString("utf8");
  if (tail.startsWith(REPLACEMENT_CHAR)) tail = tail.slice(1);
  return tail;
}

export interface OriginPolicy {
  port: number;
  /** Extra allowed origins, for example a Godot editor web preview. */
  devOrigins: string[];
}

export type GuardResult = { ok: true } | { ok: false; reason: string };

const LOOPBACK_HOSTS = ["127.0.0.1", "localhost"];

/** The Host header must name the loopback address and our port (blocks DNS rebinding). */
export function checkHost(host: string | undefined, port: number): GuardResult {
  if (!host) return { ok: false, reason: "missing Host header" };
  const normalized = host.trim().toLowerCase();
  const allowed = LOOPBACK_HOSTS.map((h) => `${h}:${port}`);
  if (allowed.includes(normalized)) return { ok: true };
  return { ok: false, reason: `Host ${host} not allowed` };
}

function normalizeOrigin(origin: string): string | null {
  try {
    const u = new URL(origin);
    if (u.origin === "null") return null;
    return u.origin.toLowerCase();
  } catch {
    return null;
  }
}

export function ownOrigins(port: number): string[] {
  return LOOPBACK_HOSTS.map((h) => `http://${h}:${port}`);
}

/**
 * Origin must be absent (desktop client), the Town Hall's own origin, or a configured
 * development origin. The literal "null" origin (sandboxed frames, file://) is refused.
 */
export function checkOrigin(origin: string | undefined, policy: OriginPolicy): GuardResult {
  if (origin === undefined) return { ok: true };
  const trimmed = origin.trim();
  if (trimmed === "" || trimmed.toLowerCase() === "null") return { ok: false, reason: "null Origin refused" };
  const normalized = normalizeOrigin(trimmed);
  if (!normalized) return { ok: false, reason: `Origin ${origin} is malformed` };
  const allowed = new Set(ownOrigins(policy.port));
  for (const dev of policy.devOrigins) {
    const n = normalizeOrigin(dev);
    if (n) allowed.add(n);
  }
  if (allowed.has(normalized)) return { ok: true };
  return { ok: false, reason: `Origin ${origin} not allowed` };
}

import path from "node:path";
import type { ApprovalCategory } from "../../protocol/objects.js";
import { currentPlatform, isInside } from "../../security/path-guard.js";
import { displayTarget } from "../common/approvals.js";
import { asNumber, asString, isPlainObject } from "../common/support.js";
import type { ApprovalRequest } from "../types.js";

/**
 * True when `target` (relative to `cwd`) names a place inside the work folder. Text a shell or
 * Codex might expand ("~", "$HOME", "%USERPROFILE%") is never taken to be inside.
 */
export function insideWorkspace(target: string, cwd: string, workspaceRoot: string): boolean {
  if (!target.trim() || /^~|[$%]/.test(target)) return false;
  return isInside(path.resolve(cwd, target), workspaceRoot, currentPlatform());
}

export type FsAccess = "read" | "write" | "deny";

export interface FsGrant {
  access: FsAccess;
  /** What the grant names, for the approval card. */
  label: string;
  /** True only for a plain path inside the work folder; globs and special locations never are. */
  inside: boolean;
}

/** A Codex permission request the Town Hall understood in full. */
export interface PermissionRequest {
  network: boolean;
  files: FsGrant[];
  /** The GrantedPermissionProfile to answer with if the player allows it: exactly what was understood. */
  profile: Record<string, unknown>;
}

const LEGACY_FS_KEYS = new Set(["read", "write", "entries", "globScanMaxDepth"]);

/** Rebuilds a FileSystemSpecialPath with only the fields its kind has; null for an unknown kind. */
function specialPath(v: unknown): { value: Record<string, unknown>; label: string } | null {
  if (!isPlainObject(v)) return null;
  const subpath = v.subpath === undefined || v.subpath === null ? null : asString(v.subpath);
  if (v.subpath !== undefined && v.subpath !== null && subpath === null) return null;
  const under = subpath ? ` (${subpath})` : "";
  switch (v.kind) {
    case "root":
      return { value: { kind: "root" }, label: "the whole file system" };
    case "minimal":
      return { value: { kind: "minimal" }, label: "the system files programs need to run" };
    case "tmpdir":
      return { value: { kind: "tmpdir" }, label: "the temp folder" };
    case "slash_tmp":
      return { value: { kind: "slash_tmp" }, label: "/tmp" };
    case "project_roots":
      return { value: { kind: "project_roots", subpath }, label: `the project roots${under}` };
    case "unknown": {
      const p = asString(v.path);
      if (!p) return null;
      return { value: { kind: "unknown", path: p, subpath }, label: `${p}${under}` };
    }
    default:
      return null;
  }
}

function hasOnly(obj: Record<string, unknown>, keys: Set<string>): boolean {
  return Object.keys(obj).every((k) => keys.has(k) || obj[k] === null || obj[k] === undefined);
}

/**
 * Reads a RequestPermissionProfile (codex app-server 0.144): network access, the legacy read and
 * write path lists, and sandbox entries (a path, a glob pattern or a special location such as
 * the drive root, each with read, write or deny access). Returns null when any part is not
 * understood, so an unfamiliar request is declined rather than granted blind.
 */
export function parsePermissionRequest(raw: unknown, cwd: string, workspaceRoot: string): PermissionRequest | null {
  if (!isPlainObject(raw) || !hasOnly(raw, new Set(["network", "fileSystem"]))) return null;
  const profile: Record<string, unknown> = {};
  let network = false;
  if (raw.network !== null && raw.network !== undefined) {
    const n = raw.network;
    if (!isPlainObject(n) || !hasOnly(n, new Set(["enabled"]))) return null;
    if (n.enabled === true) {
      network = true;
      profile.network = { enabled: true };
    } else if (n.enabled !== false && n.enabled !== null && n.enabled !== undefined) {
      return null;
    }
  }

  const files: FsGrant[] = [];
  const fs = raw.fileSystem;
  if (fs !== null && fs !== undefined) {
    if (!isPlainObject(fs) || !hasOnly(fs, LEGACY_FS_KEYS)) return null;
    const list = (v: unknown): string[] | null => {
      if (v === null || v === undefined) return [];
      return Array.isArray(v) && v.every((x) => typeof x === "string" && x.trim() !== "") ? (v as string[]) : null;
    };
    const reads = list(fs.read);
    const writes = list(fs.write);
    if (!reads || !writes) return null;
    for (const p of reads) files.push({ access: "read", label: displayTarget(p, cwd), inside: insideWorkspace(p, cwd, workspaceRoot) });
    for (const p of writes) files.push({ access: "write", label: displayTarget(p, cwd), inside: insideWorkspace(p, cwd, workspaceRoot) });

    const entries: Array<Record<string, unknown>> = [];
    if (fs.entries !== null && fs.entries !== undefined) {
      if (!Array.isArray(fs.entries)) return null;
      for (const e of fs.entries) {
        if (!isPlainObject(e) || !hasOnly(e, new Set(["path", "access"])) || !isPlainObject(e.path)) return null;
        const access = e.access;
        if (access !== "read" && access !== "write" && access !== "deny") return null;
        const p = e.path;
        if (p.type === "path") {
          const target = asString(p.path);
          if (!target || !target.trim()) return null;
          files.push({ access, label: displayTarget(target, cwd), inside: insideWorkspace(target, cwd, workspaceRoot) });
          entries.push({ path: { type: "path", path: target }, access });
        } else if (p.type === "glob_pattern") {
          const pattern = asString(p.pattern);
          if (!pattern || !pattern.trim()) return null;
          files.push({ access, label: `files matching ${pattern}`, inside: false });
          entries.push({ path: { type: "glob_pattern", pattern }, access });
        } else if (p.type === "special") {
          const special = specialPath(p.value);
          if (!special) return null;
          files.push({ access, label: special.label, inside: false });
          entries.push({ path: { type: "special", value: special.value }, access });
        } else {
          return null;
        }
      }
    }
    const depth = fs.globScanMaxDepth;
    if (depth !== null && depth !== undefined && asNumber(depth) === null) return null;
    if (reads.length > 0 || writes.length > 0 || entries.length > 0) {
      profile.fileSystem = {
        read: reads.length > 0 ? reads : null,
        write: writes.length > 0 ? writes : null,
        ...(entries.length > 0 ? { entries } : {}),
        ...(typeof depth === "number" ? { globScanMaxDepth: depth } : {}),
      };
    }
  }
  return { network, files, profile };
}

/**
 * The approval for a permission request. The category is the strictest part of it: anything
 * outside the work folder (globs and special locations included) always asks the player.
 * Each kind of request has its own tool name, so a task- or agent-wide answer to one kind never
 * covers another, and a request for network and files together can only be allowed once.
 */
export function permissionApproval(req: PermissionRequest, reason: string | null): ApprovalRequest {
  const granting = req.files.filter((f) => f.access !== "deny");
  const outside = granting.some((f) => !f.inside);
  const writes = granting.some((f) => f.access === "write");
  const category: ApprovalCategory = outside ? "outside_workspace" : req.network ? "network" : writes ? "write" : "read";
  const both = req.network && req.files.length > 0;
  const tool = both ? "permissions" : req.network ? "network_access" : "file_access";

  const labels = (access: FsAccess) => req.files.filter((f) => f.access === access).map((f) => f.label);
  const parts: string[] = [];
  if (req.network) parts.push("network access");
  if (labels("read").length > 0) parts.push(`read access to ${labels("read").join(", ")}`);
  if (labels("write").length > 0) parts.push(`write access to ${labels("write").join(", ")}`);
  const blocked = labels("deny");
  const summary = `Allow ${parts.join(" and ") || "a sandbox change"} for this turn${blocked.length > 0 ? ` (keeping ${blocked.join(", ")} blocked)` : ""}`;
  return {
    tool,
    category,
    input: { permissions: req.profile },
    summary,
    ...(both ? { risk: "high" as const } : {}),
    ...(reason ? { reason } : {}),
  };
}

