  const ground = new THREE.Mesh(new THREE.CircleGeometry(160, 64), new THREE.MeshStandardMaterial({ color: o.ground || '#8d9a5b', roughness: 1 }));
  ground.rotation.x = -Math.PI / 2; ground.receiveShadow = true; scene.add(ground);
  const plaza = new THREE.Mesh(new THREE.CircleGeometry(25, 64), new THREE.MeshStandardMaterial({ color: '#b8a17c', roughness: 1 }));
  plaza.rotation.x = -Math.PI / 2; plaza.position.y = 0.02; plaza.receiveShadow = true; scene.add(plaza);

  const pts = []; for (let x = -70; x <= 70; x += 2) pts.push(new THREE.Vector3(x, 0.05, riverZ(x)));
  const river = new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts), 200, 1.3, 6), new THREE.MeshStandardMaterial({ color: '#3f7f9c', emissive: '#1b4d6b', emissiveIntensity: 0.3, roughness: 0.2, metalness: 0.3 }));
  river.scale.y = 0.08; scene.add(river);

  const stoneMat = new THREE.MeshStandardMaterial({ color: '#cdbb9a', roughness: 0.9 });
  const roofMat = new THREE.MeshStandardMaterial({ color: '#a8472b', roughness: 0.8 });
  const wallGroups = RINGS.map((r, k) => {
    const g = new THREE.Group();
    const h = 1.2 + k * 0.5;
    const wall = new THREE.Mesh(new THREE.CylinderGeometry(r, r, h, 96, 1, true), stoneMat);
    wall.material.side = THREE.DoubleSide; wall.position.y = h / 2; wall.castShadow = wall.receiveShadow = true; g.add(wall);
    const n = 6 + k * 4;
    for (let i = 0; i < n; i++) {
      const a = (i / n) * Math.PI * 2, x = Math.cos(a) * r, z = Math.sin(a) * r;
      const t = new THREE.Mesh(new THREE.CylinderGeometry(0.6 + k * 0.1, 0.7 + k * 0.1, h * 1.7, 10), stoneMat);
      t.position.set(x, h * 0.85, z); t.castShadow = true; g.add(t);
      const c = new THREE.Mesh(new THREE.ConeGeometry(0.85 + k * 0.1, 1.4, 10), roofMat);
      c.position.set(x, h * 1.7 + 0.7, z); c.castShadow = true; g.add(c);
    }
    g.userData.h = h; scene.add(g); return g;
  });

  const castle = new THREE.Group();
  [[0, 0, 1.8, 8], [2.2, 1.4, 0.8, 5], [-2, 1.6, 0.8, 5.5], [0.4, -2.3, 0.9, 6], [-1.6, -1.4, 0.6, 4.2]].forEach(([x, z, r, h]) => {
    const t = new THREE.Mesh(new THREE.CylinderGeometry(r, r * 1.1, h, 14), stoneMat); t.position.set(x, h / 2, z); t.castShadow = true; castle.add(t);
    const c = new THREE.Mesh(new THREE.ConeGeometry(r * 1.35, r * 2.6, 14), new THREE.MeshStandardMaterial({ color: '#2f4d7a', roughness: 0.5, metalness: 0.4 })); c.position.set(x, h + r * 1.3, z); c.castShadow = true; castle.add(c);
  });
  const font = new THREE.Mesh(new THREE.TorusGeometry(1.2, 0.08, 8, 48), new THREE.MeshBasicMaterial({ color: '#ffd27a' }));
  font.position.y = 11.5; castle.add(font); scene.add(castle);

  const houses = [];
  for (let k = 0; k < 4; k++) {
    const r0 = k === 0 ? 3.4 : RINGS[k - 1] + 1.2, r1 = RINGS[k] - 1;
    const count = [40, 260, 420, 620][k];
    for (let i = 0; i < count; i++) {
      const a = Math.random() * Math.PI * 2, r = Math.sqrt(r0 * r0 + Math.random() * (r1 * r1 - r0 * r0));
      const x = Math.cos(a) * r, z = Math.sin(a) * r;
      if (Math.abs(z - riverZ(x)) < 1.9) continue;
      houses.push({ x, z, a, r, ring: k, w: 0.6 + Math.random() * 0.6, d: 0.6 + Math.random() * 0.6, h: 0.5 + Math.random() * (k < 2 ? 1.4 : 0.9), rot: -a, delay: Math.random(), bob: Math.random() * 6 });
    }
  }
  const N = houses.length;
  const houseMat = new THREE.MeshStandardMaterial({ color: '#efe2c6', roughness: 0.9, emissive: '#ffb14a', emissiveIntensity: 0 });
  const bodyI = new THREE.InstancedMesh(new THREE.BoxGeometry(1, 1, 1), houseMat, N);
  const roofG = new THREE.ConeGeometry(0.78, 0.7, 4); roofG.rotateY(Math.PI / 4);
  const roofI = new THREE.InstancedMesh(roofG, roofMat, N);
  bodyI.castShadow = roofI.castShadow = bodyI.receiveShadow = true;
  const roofCols = (o.roofs || ['#a8472b', '#b8593a', '#8f3b25', '#c26a3f', '#6f4a3a']).map(c => new THREE.Color(c));
  houses.forEach((h, i) => roofI.setColorAt(i, roofCols[i % 5]));
  scene.add(bodyI, roofI);

  const isl = [];
  const NI = o.islands ?? 5;
  if (o.hex) {
    const hx = [], cols = ['#7f9a52', '#6d8a45', '#9aa564', '#b9a26a', '#4f6f3a', '#8a8f86'].map(c => new THREE.Color(c));
    const R = 2.4, W = R * Math.sqrt(3);
    for (let q = -18; q <= 18; q++) for (let r = -18; r <= 18; r++) {
      const x = W * (q + r / 2), z = 1.5 * R * r, d = Math.hypot(x, z);
      if (d < 27 || d > 75) continue;
      hx.push({ x, z, h: 0.3 + Math.random() * (d > 50 ? 3 : 1), c: cols[(Math.random() * 6) | 0] });
    }
    const hm = new THREE.InstancedMesh(new THREE.CylinderGeometry(R * 0.96, R * 0.96, 1, 6), new THREE.MeshStandardMaterial({ roughness: 1 }), hx.length);
    const mm = new THREE.Matrix4();
    hx.forEach((h, i) => { mm.makeScale(1, h.h, 1); mm.setPosition(h.x, h.h / 2 - 0.2, h.z); hm.setMatrixAt(i, mm); hm.setColorAt(i, h.c); });
    hm.receiveShadow = hm.castShadow = true; scene.add(hm);
  }
  for (let i = 0; i < NI; i++) {
    const g = new THREE.Group();
    const rock = new THREE.Mesh(new THREE.ConeGeometry(2 + Math.random() * 1.5, 4 + Math.random() * 3, 7), new THREE.MeshStandardMaterial({ color: '#7d6a55', roughness: 1 }));
    rock.rotation.x = Math.PI; rock.position.y = -2; g.add(rock);
    const top = new THREE.Mesh(new THREE.CylinderGeometry(2.2, 2.2, 0.4, 7), new THREE.MeshStandardMaterial({ color: '#86a05a' })); g.add(top);
    const hut = new THREE.Mesh(new THREE.BoxGeometry(1, 0.9, 1), houseMat); hut.position.y = 0.65; g.add(hut);
    const rf = new THREE.Mesh(roofG, roofMat); rf.position.y = 1.4; g.add(rf);
    g.userData = { a: (i / NI) * Math.PI * 2, r: 32 + i * 4, y: 16 + i * 3 };
    scene.add(g); isl.push(g);
  }

  const P = 1400, pg = new THREE.BufferGeometry(), pp = new Float32Array(P * 3);
  for (let i = 0; i < P; i++) { const a = Math.random() * 6.28, r = Math.random() * 30; pp.set([Math.cos(a) * r, Math.random() * 24, Math.sin(a) * r], i * 3); }
  pg.setAttribute('position', new THREE.BufferAttribute(pp, 3));
  const motes = new THREE.Points(pg, new THREE.PointsMaterial({ color: '#ffd98a', size: 0.18, transparent: true, opacity: 0.7, blending: THREE.AdditiveBlending, depthWrite: false }));
  scene.add(motes);

  const sg = new THREE.BufferGeometry(), sp = new Float32Array(2000 * 3);
  for (let i = 0; i < 2000; i++) { const v = new THREE.Vector3().randomDirection().multiplyScalar(180); v.y = Math.abs(v.y) + 10; sp.set([v.x, v.y, v.z], i * 3); }
  sg.setAttribute('position', new THREE.BufferAttribute(sp, 3));
  const stars = new THREE.Points(sg, new THREE.PointsMaterial({ color: '#fff', size: 0.6, transparent: true, opacity: 0, fog: false }));
  scene.add(stars);

  const auroraMat = new THREE.ShaderMaterial({
    transparent: true, depthWrite: false, blending: THREE.AdditiveBlending, side: THREE.DoubleSide, fog: false,
    uniforms: { t: { value: 0 }, o: { value: 0 } },
    vertexShader: 'varying vec2 vU; uniform float t; void main(){ vU=uv; vec3 p=position; p.z+=sin(p.x*0.05+t*0.4)*8.0; gl_Position=projectionMatrix*modelViewMatrix*vec4(p,1.0);}',
    fragmentShader: 'varying vec2 vU; uniform float t; uniform float o; void main(){ float b=sin(vU.x*18.0+t*0.7)*0.5+0.5; float f=smoothstep(0.0,0.35,vU.y)*smoothstep(1.0,0.4,vU.y); vec3 c=mix(vec3(0.2,1.0,0.6),vec3(0.6,0.3,1.0),vU.y); gl_FragColor=vec4(c,f*b*o*0.55);}'
  });
  [0, 1].forEach(i => { const m = new THREE.Mesh(new THREE.PlaneGeometry(260, 40, 80, 1), auroraMat); m.position.set(0, 60 + i * 12, -90 - i * 20); m.rotation.x = -0.25; scene.add(m); });

  const hl = new THREE.Mesh(new THREE.RingGeometry(1, 2, 64), new THREE.MeshBasicMaterial({ color: '#ffcf6b', transparent: true, opacity: 0, side: THREE.DoubleSide, depthWrite: false }));
  hl.rotation.x = -Math.PI / 2; hl.position.y = 0.3; scene.add(hl);
  let hlTarget = 0;
  const setHighlight = i => {
    if (i == null || i < 0) { hlTarget = 0; return; }
    const d = DISTRICTS[i], r0 = d.ring === 0 ? 0.5 : RINGS[d.ring - 1], r1 = RINGS[d.ring];
    hl.geometry.dispose(); hl.geometry = new THREE.RingGeometry(r0, r1, 64, 1, d.a0, d.a1 - d.a0); hlTarget = 0.45;
  };

  const KF = o.kf || [
    { s: 0, r: 52, y: 34, a: 0.5 }, { s: 1, r: 42, y: 24, a: 0.9 }, { s: 4.6, r: 34, y: 17, a: 2.6 },
    { s: 5.3, r: 4, y: 64, a: 3.1 }, { s: 6.6, r: 4, y: 60, a: 3.3 }, { s: 7.5, r: 24, y: 6, a: 4.4 }, { s: 9, r: 22, y: 5, a: 5 },
  ];
  const camAt = s => {
    let i = 0; while (i < KF.length - 2 && s > KF[i + 1].s) i++;
    const A = KF[i], B = KF[i + 1], t = ss(A.s, B.s, s);
    return { r: A.r + (B.r - A.r) * t, y: A.y + (B.y - A.y) * t, a: A.a + (B.a - A.a) * t };
  };

  let S = 0, sCur = 0, raf, running = true;
  const m4 = new THREE.Matrix4(), q = new THREE.Quaternion(), v3 = new THREE.Vector3(), sc = new THREE.Vector3(), up = new THREE.Vector3(0, 1, 0);
  const clock = new THREE.Clock();
  const resize = () => { const w = canvas.clientWidth, h = canvas.clientHeight; renderer.setSize(w, h, false); camera.aspect = w / h; camera.updateProjectionMatrix(); };
  addEventListener('resize', resize); resize();

  const tick = () => {
    if (!running) return;
    const t = clock.getElapsedTime();
    sCur += (S - sCur) * 0.06;
    const s = sCur, e = eraOv ?? clamp(s - 0.4, 0, 4), n = nightOv ?? ss(6.7, 7.5, s);
    const c = camAt(s), a = c.a + t * 0.015;
    camera.position.set(Math.cos(a) * c.r, c.y, Math.sin(a) * c.r);
    camera.lookAt(0, o.kf ? (o.lookY ?? 2) : (s > 5 && s < 6.8 ? 0 : 2), 0);

    scene.background.copy(dawn).lerp(night, n); scene.fog.color.copy(scene.background);
    sun.color.set('#ffc78f').lerp(new THREE.Color('#7f95ff'), n); sun.intensity = 2.4 - n * 1.9;
    hemi.intensity = 0.9 - n * 0.6;
    houseMat.emissiveIntensity = n * 1.1; stars.material.opacity = n; auroraMat.uniforms.o.value = n; auroraMat.uniforms.t.value = t;
    motes.material.color.set(n > 0.5 ? '#9fe8ff' : '#ffd98a');
    const pa = motes.geometry.attributes.position;
    for (let i = 0; i < P; i++) { let y = pa.getY(i) + 0.012 + (i % 7) * 0.002; if (y > 24) y = 0; pa.setY(i, y); }
    pa.needsUpdate = true;

    wallGroups.forEach((g, k) => { const w = ease(clamp(e - k, 0, 1)); g.scale.set(1, Math.max(w, 0.001), 1); g.visible = w > 0.001; });
    const cw = ease(clamp(e * 1.3, 0, 1)); castle.scale.set(1, Math.max(cw, 0.001), 1); font.rotation.x = t * 0.8; font.rotation.y = t * 0.5;

    for (let i = 0; i < N; i++) {
      const h = houses[i];
      const vis = clamp((e - h.ring + 0.7) / 0.3, 0, 1);
      const land = ease(clamp((e - h.ring) * 1.5 - h.delay * 0.5, 0, 1));
      const lift = (1 - land) * (10 + h.delay * 12) + (1 - land) * Math.sin(t * 1.3 + h.bob) * 0.6;
      const k = Math.max(vis, 0.0001);
      q.setFromAxisAngle(up, h.rot + (1 - land) * t * 0.6);
      m4.compose(v3.set(h.x, h.h / 2 + lift, h.z), q, sc.set(h.w * k, h.h * k, h.d * k)); bodyI.setMatrixAt(i, m4);
      m4.compose(v3.set(h.x, h.h + 0.35 + lift, h.z), q, sc.set(h.w * k, k, h.d * k)); roofI.setMatrixAt(i, m4);
    }
    bodyI.instanceMatrix.needsUpdate = roofI.instanceMatrix.needsUpdate = true;

    isl.forEach((g, i) => { const u = g.userData, aa = u.a + t * 0.03; g.position.set(Math.cos(aa) * u.r, u.y + Math.sin(t * 0.5 + i) * 1.2, Math.sin(aa) * u.r); g.rotation.y = t * 0.1; });
    hl.material.opacity += (hlTarget * (0.75 + Math.sin(t * 3) * 0.25) - hl.material.opacity) * 0.1;

    renderer.render(scene, camera);
    raf = requestAnimationFrame(tick);
  };
  tick();

  return {
    setScroll: v => { S = v; },
    setEra: v => { eraOv = v; },
    setNight: v => { nightOv = v; },
    highlight: setHighlight,
    dispose: () => { running = false; cancelAnimationFrame(raf); removeEventListener('resize', resize); renderer.dispose(); },
  };
}

import { fromJson, toJson } from "../db/db.js";
import { fail } from "../protocol/errors.js";
import type {
  Agent,
  AgentActivity,
  AgentLifecycle,
  AgentStats,
  ApprovalMode,
  Billing,
  BlockedReason,
  Role,
  Seals,
  Tile,
  ToolType,
} from "../protocol/objects.js";
import { Provider } from "../protocol/objects.js";
import { displayPath, validateWorkFolder } from "../security/path-guard.js";
import type { Ctx } from "./context.js";
import { scaleCost, toResources, zeroResources, type Resources } from "./economy.js";
import type { DirtySet } from "./events.js";
import { computeRank, median, rankAtLeast } from "./ranks.js";

export interface AgentRow {
  id: string;
  name: string;
  provider: Provider;
  model: string;
  role: Role;
  instructions: string;
  approval_mode: ApprovalMode;
  workspace_path: string;
  workspace_mode: "git_worktree" | "plain_folder";
  repo_root: string | null;
  workspace_sub: string;
  mirror_path: string | null;
  workspace_ready: number;
  workspace_error: string | null;
  seals_json: string;
  billing: Billing;
  lifecycle: AgentLifecycle;
  activity: AgentActivity;
  blocked_reason: BlockedReason | null;
  home_tile_json: string | null;
  home_built: number;
  xp: number;
  level: number;
  rank: string;
  stats_json: string;
  party_id: string | null;
  grace: number;
  cost_json: string;
  starting_tools_json: string;
  retire_after_current: number;
  version: number;
  created_at: string;
  retired_at: string | null;
}

export interface CreateAgentSpec {
  name: string;
  provider: Provider;
  model: string;
  role: Role;
  instructions: string;
  approval_mode?: ApprovalMode | undefined;
  workspace: { path: string };
  seals?: Partial<Seals> | undefined;
  billing?: Billing | undefined;
  starting_tools: ToolType[];
}

export interface AgentPatch {
  name?: string | undefined;
  model?: string | undefined;
  instructions?: string | undefined;
  approval_mode?: ApprovalMode | undefined;
  seals?: Partial<Seals> | undefined;
}

const EMPTY_STATS: AgentStats = {
  accepted: 0,
  accepted_first_try: 0,
  sent_back: 0,
  failed: 0,
  rites_passed: 0,
  party_tasks: 0,
  mana_spent_micros: 0,
};

const ACTIVE_TASK_STATES = "('preparing','running','awaiting_approval')";

export class AgentService {
  private readonly dirty: DirtySet;

  constructor(private readonly ctx: Ctx) {
    this.dirty = ctx.bus.newDirtySet();
    ctx.bus.addFlusher(() => this.flush());
  }

  markDirty(agentId: string): void {
    if (this.ctx.db.inTx()) this.dirty.add(agentId);
    else this.ctx.db.tx(() => this.dirty.add(agentId));
  }

  private flush(): boolean {
    const ids = this.dirty.take();
    for (const id of ids) {
      const row = this.rowOrNull(id);
      if (!row) continue;
      const s = this.computeStatus(row);
      this.ctx.db.run(
        "UPDATE agents SET lifecycle = ?, activity = ?, blocked_reason = ?, version = version + 1 WHERE id = ?",
        [s.lifecycle, s.activity, s.blocked_reason, id],
      );
      const agent = this.toProtocol(this.row(id));
      this.ctx.bus.emit("agent_updated", { agent }, `agent/${id}`);
    }
    return ids.length > 0;
  }

  rowOrNull(id: string): AgentRow | null {
    return this.ctx.db.get<AgentRow>("SELECT * FROM agents WHERE id = ?", [id]) ?? null;
  }

  row(id: string): AgentRow {
    const r = this.rowOrNull(id);
    if (!r) throw fail.notFound("agent", id);
    return r;
  }

  seals(r: AgentRow): Seals {
    return fromJson<Seals>(r.seals_json, this.defaultSeals());
  }

  stats(r: AgentRow): AgentStats {
    return { ...EMPTY_STATS, ...fromJson<Partial<AgentStats>>(r.stats_json, {}) };
  }

  private defaultSeals(): Seals {
    const s = this.ctx.econ.data.mana.seal_by_size;
    return { S: s.S, M: s.M, L: s.L, XL: s.XL };
  }

  currentTaskId(agentId: string): string | null {
    return (
      this.ctx.db.get<{ id: string }>(
        `SELECT id FROM tasks WHERE agent_id = ? AND state IN ${ACTIVE_TASK_STATES} ORDER BY started_at LIMIT 1`,
        [agentId],
      )?.id ?? null
    );
  }

  queue(agentId: string): string[] {
    return this.ctx.db
      .all<{ id: string }>(
        "SELECT id FROM tasks WHERE agent_id = ? AND state IN ('in_transit','queued') ORDER BY queue_pos ASC, created_at ASC",
        [agentId],
      )
      .map((r) => r.id);
  }

  toProtocol(r: AgentRow): Agent {
    const tile = fromJson<Tile | null>(r.home_tile_json, null);
    return {
      id: r.id,
      name: r.name,
      provider: r.provider,
      model: r.model,
      role: r.role,
      instructions: r.instructions,
      approval_mode: r.approval_mode,
      workspace: {
        path: displayPath(r.workspace_path),
        mode: r.workspace_mode,
        repo_root: r.repo_root ? displayPath(r.repo_root) : null,
      },
      seals: this.seals(r),
      billing: r.billing,
      lifecycle: r.lifecycle,
      activity: r.activity,
      blocked_reason: r.blocked_reason,
      home: tile ? { tile, built: r.home_built === 1 } : null,
      tool_ids: this.ctx.tools.idsForAgent(r.id),
      starting_tools: fromJson<ToolType[]>(r.starting_tools_json, []),
      current_task_id: this.currentTaskId(r.id),
      queue: this.queue(r.id),
      xp: r.xp,
      level: r.level,
      rank: r.rank,
      stats: this.stats(r),
      party_id: r.party_id,
      version: r.version,
      created_at: r.created_at,
    };
  }

  get(id: string): Agent {
    return this.toProtocol(this.row(id));
  }

  list(): Agent[] {
    return this.ctx.db.all<AgentRow>("SELECT * FROM agents ORDER BY created_at ASC").map((r) => this.toProtocol(r));
  }

  nonRetiredCount(): number {
    return this.ctx.db.get<{ n: number }>("SELECT COUNT(*) AS n FROM agents WHERE retired_at IS NULL")?.n ?? 0;
  }

  /** Lifecycle, activity and blocked reason derived from tools, tasks, Mana and the provider. */
  private computeStatus(r: AgentRow): { lifecycle: AgentLifecycle; activity: AgentActivity; blocked_reason: BlockedReason | null } {
    if (r.retired_at) return { lifecycle: "retired", activity: "idle", blocked_reason: null };
    if (r.lifecycle === "training") return { lifecycle: "training", activity: "idle", blocked_reason: null };
    const toolsOk = this.ctx.tools.requiredToolsActive(r.id, r.role);
    let lifecycle: AgentLifecycle = r.lifecycle;
    if (lifecycle === "settling" && r.home_built === 1 && toolsOk && r.workspace_ready === 1) lifecycle = "active";
    const currentId = this.currentTaskId(r.id);
    if (currentId) {
      const state = this.ctx.db.get<{ state: string }>("SELECT state FROM tasks WHERE id = ?", [currentId])?.state;
      return { lifecycle, activity: state === "awaiting_approval" ? "awaiting_approval" : "working", blocked_reason: null };
    }
    if (r.home_built !== 1) return { lifecycle, activity: "idle", blocked_reason: null };
    if (!toolsOk) return { lifecycle, activity: "blocked", blocked_reason: "missing_tools" };
    if (r.workspace_error) return { lifecycle, activity: "blocked", blocked_reason: "workspace_error" };
    if (r.workspace_ready !== 1) return { lifecycle, activity: "idle", blocked_reason: null };
    if (!this.ctx.providers.isOnline(r.provider)) return { lifecycle, activity: "blocked", blocked_reason: "provider_offline" };
    const next = this.ctx.tasks.nextQueued(r.id);
    if (next && !this.ctx.mana.canStart(next).ok) return { lifecycle, activity: "blocked", blocked_reason: "no_mana" };
    return { lifecycle, activity: "idle", blocked_reason: null };
  }

  /** True when the agent can be given a new run right now (lifecycle and blockers only). */
  isDispatchable(r: AgentRow): boolean {
    if (r.retired_at || r.lifecycle !== "active") return false;
    if (r.workspace_ready !== 1 || r.workspace_error) return false;
    if (!this.ctx.tools.requiredToolsActive(r.id, r.role)) return false;
    return this.ctx.providers.isOnline(r.provider);
  }

  private checkApprovalMode(mode: ApprovalMode, provider: Provider, rank: string): void {
    const def = this.ctx.econ.data.approval_modes[mode];
    if (!def) throw fail.badRequest(`unknown approval mode ${mode}`);
    const age = this.ctx.ages.current();
    if (def.age > age) throw fail.age(`${mode} needs Age ${def.age}`);
    if (!rankAtLeast(this.ctx.econ, rank, def.min_rank)) throw fail.rank(`${mode} needs rank ${def.min_rank}`);
    if (def.providers && !def.providers.includes(provider)) {
      throw fail.badRequest(`${mode} is only available for ${def.providers.join(", ")}`);
    }
  }

  /** pi serves many model providers, so a pi agent's model names both: "<pi provider>/<model id>". */
  private checkModel(provider: Provider, model: string): void {
    if (provider === "pi" && !/^[A-Za-z0-9._-]+\/\S+$/.test(model.trim())) {
      throw fail.badRequest('a pi model is written "<pi provider>/<model id>", for example "openrouter/deepseek/deepseek-chat"');
    }
  }

  private defaultApprovalMode(): ApprovalMode {
    const entry = Object.entries(this.ctx.econ.data.approval_modes).find(([, v]) => v.default === true);
    return (entry?.[0] ?? "trusted_edits") as ApprovalMode;
  }

  agentCost(role: Role): Resources {
    const def = this.ctx.econ.data.roles[role];
    if (!def) throw fail.badRequest(`unknown role ${role}`);
    const existing = this.nonRetiredCount();
    return scaleCost(def.cost, 1 + this.ctx.econ.data.agent_cost_scaling_per_existing * existing);
  }

  private graceApplies(): boolean {
    return this.nonRetiredCount() === this.ctx.econ.data.anti_deadlock.fonts_grace.when_agents;
  }

  graceFrees(r: AgentRow, what: "agent" | "home" | "required_tools"): boolean {
    return r.grace === 1 && this.ctx.econ.data.anti_deadlock.fonts_grace.free.includes(what);
  }

  async create(spec: CreateAgentSpec): Promise<{ agent_id: string; cost: Resources; free: boolean; training: { duration_ms: number } }> {
    const econ = this.ctx.econ;
    const role = econ.data.roles[spec.role];
    if (!role) throw fail.badRequest(`unknown role ${spec.role}`);
    const age = this.ctx.ages.current();
    if (role.age > age) throw fail.age(`${role.name} can be summoned from Age ${role.age}`);
    const mode = spec.approval_mode ?? this.defaultApprovalMode();
    this.checkApprovalMode(mode, spec.provider, econ.rankOrder[0]!);
    this.checkModel(spec.provider, spec.model);
    if (this.nonRetiredCount() >= econ.agentLimit(age)) {
      throw fail.limit(`Age ${age} allows at most ${econ.agentLimit(age)} agents`);
    }
    if (!this.ctx.providers.isOnline(spec.provider)) throw fail.provider(`${spec.provider} is not available`);
    const checked = validateWorkFolder(spec.workspace.path, this.ctx.pathPolicy);
    if (!checked.ok) throw fail.workspace(checked.reason);
    const detected = await this.ctx.workspace.detect(checked.path);

    return this.ctx.db.tx(() => {
      // Re-check limits inside the transaction: another create may have finished meanwhile.
      if (this.nonRetiredCount() >= econ.agentLimit(age)) {
        throw fail.limit(`Age ${age} allows at most ${econ.agentLimit(age)} agents`);
      }
      const grace = this.graceApplies();
      const free = grace && econ.data.anti_deadlock.fonts_grace.free.includes("agent");
      const cost = free ? zeroResources() : this.agentCost(spec.role);
      const id = this.ctx.ids.next("agt");
      const seals = { ...this.defaultSeals(), ...(spec.seals ?? {}) };
      const billing = spec.billing ?? this.ctx.mana.defaultBilling(spec.provider);
      this.ctx.treasury.charge(cost, "agent", id, `agent:${id}`);
      this.ctx.db.run(
        `INSERT INTO agents (id, name, provider, model, role, instructions, approval_mode, workspace_path, workspace_mode,
           repo_root, workspace_sub, seals_json, billing, lifecycle, activity, stats_json, grace, cost_json,
           starting_tools_json, created_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'training', 'idle', ?, ?, ?, ?, ?)`,
        [
          id,
          spec.name,
          spec.provider,
          spec.model,
          spec.role,
          spec.instructions,
          mode,
          checked.path,
          detected.mode,
          detected.repoRoot,
          detected.sub,
          toJson(seals),
          billing,
          toJson(EMPTY_STATS),
          grace ? 1 : 0,
          toJson(cost),
          toJson(spec.starting_tools),
          this.ctx.clock.iso(),
        ],
      );
      this.markDirty(id);
      this.ctx.mana.markDirty();
      return { agent_id: id, cost, free, training: { duration_ms: Math.round(role.train_s * 1000) } };
    });
  }

  trained(agentId: string): void {
    this.ctx.db.tx(() => {
      const r = this.row(agentId);
      if (r.lifecycle !== "training") {
        if (r.lifecycle === "retired") throw fail.invalidState("the agent is retired");
        return;
      }
      this.ctx.db.run("UPDATE agents SET lifecycle = 'settling' WHERE id = ?", [agentId]);
      this.markDirty(agentId);
    });
  }

  placeHome(agentId: string, tile: Tile): { cost: Resources } {
    return this.ctx.db.tx(() => {
      const r = this.row(agentId);
      if (r.lifecycle === "training") throw fail.invalidState("the agent is still training");
      if (r.lifecycle === "retired") throw fail.invalidState("the agent is retired");
      if (r.home_tile_json) throw fail.invalidState("the agent already has a home");
      const home = this.ctx.econ.data.buildings[this.ctx.econ.data.roles[r.role]!.home];
      const cost = this.graceFrees(r, "home") ? zeroResources() : toResources(home?.cost ?? {});
      this.ctx.treasury.charge(cost, "home", agentId, `home:${agentId}`);
      this.ctx.db.run("UPDATE agents SET home_tile_json = ? WHERE id = ?", [toJson(tile), agentId]);
      this.markDirty(agentId);
      return { cost };
    });
  }

  homeBuilt(agentId: string): void {
    const shouldSetup = this.ctx.db.tx(() => {
      const r = this.row(agentId);
      if (!r.home_tile_json) throw fail.invalidState("the home has not been placed");
      if (r.retired_at) throw fail.invalidState("the agent is retired");
      if (r.home_built === 1) return false;
      this.ctx.db.run("UPDATE agents SET home_built = 1 WHERE id = ?", [agentId]);
      this.markDirty(agentId);
      return true;
    });
    if (shouldSetup) void this.setupWorkspace(agentId);
  }

  /** Prepares the agent's workspace (repo check or versioned plain-folder copy) in the background. */
  async setupWorkspace(agentId: string): Promise<void> {
    const r = this.row(agentId);
    try {
      const mirror = await this.ctx.workspace.setupAgent(r);
      this.ctx.db.tx(() => {
        this.ctx.db.run("UPDATE agents SET workspace_ready = 1, workspace_error = NULL, mirror_path = ? WHERE id = ?", [
          mirror,
          agentId,
        ]);
        this.markDirty(agentId);
      });
      this.ctx.scheduler.kick();
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      this.ctx.log.warn({ agentId, err: message }, "workspace setup failed");
      this.ctx.db.tx(() => {
        this.ctx.db.run("UPDATE agents SET workspace_error = ? WHERE id = ?", [message.slice(0, 500), agentId]);
        this.markDirty(agentId);
      });
    }
  }

  update(agentId: string, patch: AgentPatch, expectedVersion: number): Agent {
    this.ctx.db.tx(() => {
      const r = this.row(agentId);
      if (r.version !== expectedVersion) throw fail.conflict(`agent version is ${r.version}, not ${expectedVersion}`);
      if (r.retired_at) throw fail.invalidState("the agent is retired");
      if (patch.approval_mode) this.checkApprovalMode(patch.approval_mode, r.provider, r.rank);
      if (patch.model !== undefined) this.checkModel(r.provider, patch.model);
      const seals = patch.seals ? { ...this.seals(r), ...patch.seals } : this.seals(r);
      this.ctx.db.run(
        "UPDATE agents SET name = ?, model = ?, instructions = ?, approval_mode = ?, seals_json = ? WHERE id = ?",
        [
          patch.name ?? r.name,
          patch.model ?? r.model,
          patch.instructions ?? r.instructions,
          patch.approval_mode ?? r.approval_mode,
          toJson(seals),
          agentId,
        ],
      );
      this.markDirty(agentId);
    });
    return this.get(agentId);
  }

  retire(agentId: string, when: "now" | "after_current"): void {
    const r = this.row(agentId);
    if (r.retired_at) return;
    if (when === "after_current" && this.currentTaskId(agentId)) {
      this.ctx.db.tx(() => {
        this.ctx.db.run("UPDATE agents SET retire_after_current = 1 WHERE id = ?", [agentId]);
        this.ctx.tasks.cancelQueuedForAgent(agentId);
        this.markDirty(agentId);
      });
      return;
    }
    this.retireNow(agentId);
  }

  retireNow(agentId: string): void {
    this.ctx.tasks.cancelAllForAgent(agentId);
    this.ctx.db.tx(() => {
      const r = this.row(agentId);
      if (r.retired_at) return;
      if (r.lifecycle === "training") {
        const paid = toResources(fromJson(r.cost_json, {}));
        const factor = this.ctx.econ.data.refunds.cancel;
        const refund = scaleCost(paid, factor, Math.floor);
        this.ctx.treasury.credit(refund, "cancel_refund", "agent_cancelled", agentId, `agent_cancel:${agentId}`);
      }
      this.ctx.tools.removeAllForAgent(agentId);
      this.ctx.parties.onAgentRetired(agentId);
      this.ctx.db.run("UPDATE agents SET retired_at = ?, lifecycle = 'retired', party_id = NULL WHERE id = ?", [
        this.ctx.clock.iso(),
        agentId,
      ]);
      this.markDirty(agentId);
      this.ctx.bus.emit("agent_retired", { agent_id: agentId }, `agent/${agentId}`);
      this.ctx.mana.markDirty();
    });
  }

  /** Called when an agent's run ends: honours `retire_agent{when:"after_current"}`. */
  maybeRetireAfterCurrent(agentId: string): void {
    const r = this.rowOrNull(agentId);
    if (!r || r.retired_at || r.retire_after_current !== 1) return;
    if (this.currentTaskId(agentId)) return;
    this.retireNow(agentId);
  }

  setParty(agentId: string, partyId: string | null): void {
    this.ctx.db.run("UPDATE agents SET party_id = ? WHERE id = ?", [partyId, agentId]);
    this.markDirty(agentId);
  }

  addManaSpent(agentId: string, micros: number): void {
    this.bumpStats(agentId, { mana_spent_micros: micros });
  }

  bumpStats(agentId: string, delta: Partial<AgentStats>): void {
    this.ctx.db.tx(() => {
      const r = this.row(agentId);
      const s = this.stats(r);
      for (const [k, v] of Object.entries(delta) as Array<[keyof AgentStats, number]>) s[k] += v;
      this.ctx.db.run("UPDATE agents SET stats_json = ? WHERE id = ?", [toJson(s), agentId]);
      this.markDirty(agentId);
    });
  }

  /** Adds XP, then recomputes level and rank. */
  addXp(agentId: string, xp: number): void {
    this.ctx.db.tx(() => {
      const r = this.row(agentId);
      const total = r.xp + Math.max(0, Math.round(xp));
      this.ctx.db.run("UPDATE agents SET xp = ?, level = ? WHERE id = ?", [total, this.ctx.econ.levelForXp(total), agentId]);
      this.recomputeRank(agentId);
    });
  }

  recomputeRank(agentId: string): void {
    this.ctx.db.tx(() => {
      const r = this.row(agentId);
      const stats = this.stats(r);
      const window = this.ctx.econ.data.rank_first_try_window;
      const recent = this.ctx.db.all<{ attempt: number; mana_used_micros: number | null; baseline_micros: number | null }>(
        "SELECT attempt, mana_used_micros, baseline_micros FROM tasks WHERE agent_id = ? AND accepted_at IS NOT NULL AND parent_task_id IS NULL ORDER BY accepted_at DESC LIMIT ?",
        [agentId, window],
      );
      const firstTry = recent.filter((t) => t.attempt === 1).length;
      const ratios = recent
        .filter((t) => t.mana_used_micros !== null && t.baseline_micros)
        .map((t) => t.mana_used_micros! / t.baseline_micros!);
      const rank = computeRank(this.ctx.econ, {
        xp: r.xp,
        accepted: stats.accepted,
        firstTryRate: recent.length ? firstTry / recent.length : 0,
        ritesPassed: stats.rites_passed,
        partyTasks: stats.party_tasks,
        medianManaRatio: median(ratios),
        townAge: this.ctx.ages.current(),
      });
      if (rank !== r.rank) this.ctx.db.run("UPDATE agents SET rank = ? WHERE id = ?", [rank, agentId]);
      this.markDirty(agentId);
    });
  }

  applyBillingDefaults(billing: Record<Provider, Billing>): void {
    for (const provider of Provider.options) {
      const rows = this.ctx.db.all<{ id: string }>(
        "SELECT id FROM agents WHERE provider = ? AND retired_at IS NULL AND billing != ?",
        [provider, billing[provider]],
      );
      for (const row of rows) {
        this.ctx.db.run("UPDATE agents SET billing = ? WHERE id = ?", [billing[provider], row.id]);
        this.markDirty(row.id);
      }
    }
  }

  /** Marks every non-retired agent dirty (after Mana or provider changes that affect blockers). */
  refreshAll(): void {
    this.ctx.db.tx(() => {
      for (const r of this.ctx.db.all<{ id: string }>("SELECT id FROM agents WHERE retired_at IS NULL")) this.markDirty(r.id);
    });
  }

  /** Recompute the stored status of agents and emit only if something visible changed. */
  refreshIfChanged(agentId: string): void {
    const r = this.rowOrNull(agentId);
    if (!r) return;
    const s = this.computeStatus(r);
    if (s.lifecycle !== r.lifecycle || s.activity !== r.activity || s.blocked_reason !== r.blocked_reason) {
      this.markDirty(agentId);
    }
  }
}

import type { Incident, IncidentKind, IncidentSeverity } from "../protocol/objects.js";
import type { Ctx } from "./context.js";

interface IncidentRow {
  id: string;
  kind: IncidentKind;
  severity: IncidentSeverity;
  agent_id: string | null;
  task_id: string | null;
  key: string;
  message: string;
  opened_at: string;
  resolved_at: string | null;
}

export interface OpenIncident {
  severity: IncidentSeverity;
  message: string;
  agentId?: string | null;
  taskId?: string | null;
}

/** Keys identify one open incident per condition, so opening twice is a no-op. */
export const incidentKey = {
  smoke: (taskId: string) => `smoke:${taskId}`,
  alarm: (taskId: string) => `alarm:${taskId}`,
  handApproval: (approvalId: string) => `hand:${approvalId}`,
  handSeal: (taskId: string) => `hand:seal:${taskId}`,
  dimLanterns: () => "dim_lanterns",
  fontDark: () => "font_dark",
  fontDarkProvider: (provider: string) => `font_dark:provider:${provider}`,
  rift: (taskId: string) => `rift:${taskId}`,
  merge: (taskId: string) => `merge:${taskId}`,
};

function toIncident(r: IncidentRow): Incident {
  return {
    id: r.id,
    kind: r.kind,
    severity: r.severity,
    subject: { agent_id: r.agent_id, task_id: r.task_id },
    message: r.message,
    opened_at: r.opened_at,
  };
}

export class IncidentService {
  constructor(private readonly ctx: Ctx) {}

  open(kind: IncidentKind, key: string, spec: OpenIncident): Incident {
    return this.ctx.db.tx(() => {
      const existing = this.ctx.db.get<IncidentRow>("SELECT * FROM incidents WHERE key = ? AND resolved_at IS NULL", [
        key,
      ]);
      if (existing) return toIncident(existing);
      const row: IncidentRow = {
        id: this.ctx.ids.next("inc"),
        kind,
        severity: spec.severity,
        agent_id: spec.agentId ?? null,
        task_id: spec.taskId ?? null,
        key,
        message: this.ctx.redactor.redact(spec.message),
        opened_at: this.ctx.clock.iso(),
        resolved_at: null,
      };
      this.ctx.db.run(
        "INSERT INTO incidents (id, kind, severity, agent_id, task_id, key, message, opened_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
        [row.id, row.kind, row.severity, row.agent_id, row.task_id, row.key, row.message, row.opened_at],
      );
      const incident = toIncident(row);
      this.ctx.bus.emit("incident_opened", { incident }, `incident/${row.id}`);
      return incident;
    });
  }

  resolve(key: string): boolean {
    return this.ctx.db.tx(() => {
      const row = this.ctx.db.get<IncidentRow>("SELECT * FROM incidents WHERE key = ? AND resolved_at IS NULL", [key]);
      if (!row) return false;
      this.ctx.db.run("UPDATE incidents SET resolved_at = ? WHERE id = ?", [this.ctx.clock.iso(), row.id]);
      this.ctx.bus.emit("incident_resolved", { incident_id: row.id }, `incident/${row.id}`);
      return true;
    });
  }

  resolveForTask(taskId: string, kinds: IncidentKind[]): void {
    this.ctx.db.tx(() => {
      const rows = this.ctx.db.all<IncidentRow>(
        "SELECT * FROM incidents WHERE task_id = ? AND resolved_at IS NULL",
        [taskId],
      );
      for (const r of rows) if (kinds.includes(r.kind)) this.resolve(r.key);
    });
  }

  isOpen(key: string): boolean {
    return !!this.ctx.db.get("SELECT id FROM incidents WHERE key = ? AND resolved_at IS NULL", [key]);
  }

  listOpen(): Incident[] {
    return this.ctx.db
      .all<IncidentRow>("SELECT * FROM incidents WHERE resolved_at IS NULL ORDER BY opened_at ASC")
      .map(toIncident);
  }
}

import { readFileSync } from "node:fs";
import { z } from "zod";

const PriceEntry = z.looseObject({
  provider: z.string(),
  input: z.number().min(0),
  cache_write: z.number().min(0),
  cache_read: z.number().min(0),
  output: z.number().min(0),
  estimated: z.array(z.string()).optional(),
});
export type PriceEntry = z.infer<typeof PriceEntry>;

const PricingFile = z.looseObject({
  unit: z.string().optional(),
  models: z.record(z.string(), PriceEntry),
  aliases: z.record(z.string(), z.string()).default({}),
  fallback_by_provider: z.record(z.string(), z.string()).default({}),
});
type PricingData = z.infer<typeof PricingFile>;

/** Token counts for one request or a sum of requests. `input` excludes cached input. */
export interface TokenUsage {
  input: number;
  cacheRead: number;
  cacheWrite: number;
  output: number;
}

export function emptyUsage(): TokenUsage {
  return { input: 0, cacheRead: 0, cacheWrite: 0, output: 0 };
}

export interface PriceMatch {
  id: string;
  entry: PriceEntry;
  /** True when the model was unknown and the provider's fallback price was used. */
  fallback: boolean;
}

/** protocol/pricing.json: USD per million tokens, by model. */
export class Pricing {
  constructor(private readonly data: PricingData) {}

  static load(file: string): Pricing {
    const parsed = PricingFile.safeParse(JSON.parse(readFileSync(file, "utf8")) as unknown);
    if (!parsed.success) throw new Error(`pricing.json is invalid: ${parsed.error.issues[0]?.message ?? "bad shape"}`);
    return new Pricing(parsed.data);
  }

  static empty(): Pricing {
    return new Pricing({ models: {}, aliases: {}, fallback_by_provider: {} });
  }

  /** Normalises a harness model name: case, the "[1m]" context suffix, dates, aliases. */
  canonical(model: string): string | null {
    let id = model.trim().toLowerCase().replace(/\[[^\]]*\]$/, "");
    if (this.data.models[id]) return id;
    if (this.data.aliases[id]) return this.data.aliases[id]!;
    id = id.replace(/-\d{8}$/, "");
    if (this.data.models[id]) return id;
    if (this.data.aliases[id]) return this.data.aliases[id]!;
    return null;
  }

  match(provider: string, model: string): PriceMatch | null {
    const id = this.canonical(model);
    if (id && this.data.models[id]) return { id, entry: this.data.models[id]!, fallback: false };
    const fallbackId = this.data.fallback_by_provider[provider];
    if (fallbackId && this.data.models[fallbackId]) return { id: fallbackId, entry: this.data.models[fallbackId]!, fallback: true };
    return null;
  }

  /** Cost in USD of the given tokens, or null when no price is known for the provider. */
  costUsd(provider: string, model: string, usage: TokenUsage): number | null {
    const m = this.match(provider, model);
    if (!m) return null;
    const e = m.entry;
    const usd =
      (Math.max(0, usage.input) * e.input +
        Math.max(0, usage.cacheRead) * e.cache_read +
        Math.max(0, usage.cacheWrite) * e.cache_write +
        Math.max(0, usage.output) * e.output) /
      1_000_000;
    return usd;
  }

  /** A short price label for list_models, for example "$1.00 in / $5.00 out per 1M tokens". */
  costHint(provider: string, model: string): string | undefined {
    const m = this.match(provider, model);
    if (!m || m.fallback) return undefined;
    const f = (n: number) => `$${n.toFixed(2)}`;
    return `${f(m.entry.input)} in / ${f(m.entry.output)} out per 1M tokens`;
  }

  /** Model ids priced for a provider, cheapest input first. */
  models(provider: string): string[] {
    return Object.entries(this.data.models)
      .filter(([, e]) => e.provider === provider)
      .sort((a, b) => a[1].input + a[1].output - (b[1].input + b[1].output))
      .map(([id]) => id);
  }
}

export function usdToMicros(usd: number): number {
  return Math.max(0, Math.round(usd * 1_000_000));
}

/**
 * Turns a running USD total (Claude Code's `total_cost_usd`) into charges. Each update charges
 * the growth since the last one; a drop (a restarted counter) charges nothing and rebases.
 */
export class RunningTotal {
  private last: number;

  constructor(baselineUsd = 0) {
    this.last = baselineUsd;
  }

  get value(): number {
    return this.last;
  }

  /** Returns the new spend in micro-USD since the previous total. */
  update(totalUsd: number): number {
    if (!Number.isFinite(totalUsd) || totalUsd < 0) return 0;
    const delta = totalUsd - this.last;
    this.last = totalUsd;
    return delta > 0 ? usdToMicros(delta) : 0;
  }
}
